def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    blue_book_patches = image_patch.find("blue book")
    if not blue_book_patches:
        return image_patch

    blue_book = blue_book_patches[0]

    shelf_patches = image_patch.find("shelf")
    if not shelf_patches:
        return image_patch

    under_shelf = [s for s in shelf_patches if s.overlaps_with(blue_book.left, blue_book.lower, blue_book.right, blue_book.upper)]

    if not under_shelf:
        return image_patch

    return under_shelf[0]

